{
  "rationale": "To build a comprehensive profile for Microsoft Corporation (MSFT), I will gather basic company facts and executive leadership, collect recent financial statements, analyze peer valuations, calculate key financial metrics using the calculation engine, and review recent developments via web search.",
  "steps": [
    {
      "id": "s1",
      "goal": "Get basic details about Microsoft including sector, industry, market cap, headquarters, and key executives",
      "tool": "company_profile",
      "args": {
        "ticker": "MSFT"
      },
      "depends_on": [],
      "reason": "Provides core information for company overview and key executives section."
    },
    {
      "id": "s2",
      "goal": "Retrieve income statement data for the last 3 annual periods",
      "tool": "financial_data_api",
      "args": {
        "ticker": "MSFT",
        "statement_type": "income_statement",
        "period": "annual",
        "years": 3
      },
      "depends_on": [],
      "reason": "Obtain historical revenue, operating income, and net income for financial analysis."
    },
    {
      "id": "s3",
      "goal": "Retrieve balance sheet data for the last 3 annual periods",
      "tool": "financial_data_api",
      "args": {
        "ticker": "MSFT",
        "statement_type": "balance_sheet",
        "period": "annual",
        "years": 3
      },
      "depends_on": [],
      "reason": "Obtain cash, debt, and equity metrics for financial summary."
    },
    {
      "id": "s4",
      "goal": "Retrieve cash flow statement data for the last 3 annual periods",
      "tool": "financial_data_api",
      "args": {
        "ticker": "MSFT",
        "statement_type": "cash_flow",
        "period": "annual",
        "years": 3
      },
      "depends_on": [],
      "reason": "Obtain operating cash flow and capital expenditures to evaluate free cash flow."
    },
    {
      "id": "s5",
      "goal": "Compare MSFT relative valuation and performance against major technology peers",
      "tool": "peer_comparison",
      "args": {
        "ticker": "MSFT",
        "metrics": ["revenue", "revenue_growth", "gross_margin", "operating_margin", "pe_ratio", "market_cap"]
      },
      "depends_on": [],
      "reason": "Provides comparative context for financial performance and market positioning."
    },
    {
      "id": "s6",
      "goal": "Calculate Microsoft's latest annual revenue growth rate and operating margin",
      "tool": "calculation_engine",
      "args": null,
      "depends_on": ["s2"],
      "reason": "Ensure exact calculation of growth and profitability metrics per principle P2."
    },
    {
      "id": "s7",
      "goal": "Search recent web news and corporate announcements regarding Microsoft's key developments",
      "tool": "web_search",
      "args": {
        "query": "Microsoft strategic developments acquisitions product launches FY2026",
        "num_results": 10
      },
      "depends_on": [],
      "reason": "Gather recent business context and strategic developments not captured in financial statements."
    }
  ]
}
